        res_0 = requests \
                .post(self.baseUrlOfSut + "/v1/tenant/upgrade/execute",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "Admin API key required"
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"step_id\" : \"_QDYRunpObf\", " + \
            " \"force\" : false " + \
            " } "
        headers['Accept'] = "application/json"
        res_1 = requests \
                .post(self.baseUrlOfSut + "/v1/tenant/upgrade/execute",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
